0,"Write a Python script that processes a text file containing lines of JSON objects. The script should read the input file, validate each JSON object, and then convert those objects into XML format. The converted XML data should be written to an output file. The script should accept three command-line arguments: the name of the input file, the name of the output file, and a configuration file specifying JSON-to-XML conversion rules. The script should handle errors gracefully, provide informative error messages for invalid JSON or configuration issues, and utilize standard library functions for I/O operations and parsing JSON and XML data.",120,,"['```python
import sys
import json
import xml.etree.ElementTree as ET

def validate_json(json_obj):
    try:
        json.loads(json_obj)
    except ValueError as e:
        print(f""Invalid JSON: {e}"", file=sys.stderr)
        return False
    return True

def convert_to_xml(json_obj, rules):
    root = ET.Element(""root"")
    for key, value in json_obj.items():
        if isinstance(value, dict):
            sub_element = ET.SubElement(root, key)
            for sub_key, sub_value in value.items():
                if sub_key in rules:
                    new_sub_element = ET.SubElement(sub_element, rules[sub_key])
                    new_sub_element.text = str(sub_value)
                else:
                    print(f""No rule found for {sub_key}"", file=sys.stderr)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    sub_element = ET.SubElement(root, key)
                    for sub_key, sub_value in item.items():
                        if sub_key in rules:
                            new_sub_element = ET.SubElement(sub_element, rules[sub_key])
                            new_sub_element.text = str(sub_value)
                        else:
                            print(f""No rule found for {sub_key}"", file=sys.stderr)
                else:
                    sub_element = ET.SubElement(root, key)
                    sub_element.text = str(item)
        else:
            if key in rules:
                sub_element = ET.SubElement(root, rules[key])
                sub_element.text = str(value)
            else:
                print(f""No rule found for {key}"", file=sys.stderr)
    return root

def process_files(input_file, output_file, config_file):
    try:
        with open(config_file, 'r') as f:
            rules = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f""Error reading configuration file: {e}"", file=sys.stderr)
        return

    tree = ET.ElementTree()
    root = ET.Element(""root"")
    tree._setroot(root)

    with open(input_file, 'r') as f:
        for line in f:
            if validate_json(line):
                json_obj = json.loads(line)
                xml_subtree = convert_to_xml(json_obj, rules)
                tree.getroot().extend(xml_subtree)

    tree.write(output_file, encoding='utf-8', xml_declaration=True)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file> <output_file> <config_file>"", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    config_file = sys.argv[3]

    process_files(input_file, output_file, config_file)
```']",3,[0],[],True,0,0,0,

