0,"Create a program that efficiently handles image caching for a web application. The code should first verify if an image is already in the cache and has been loaded. If not, it should load the image, store it in the cache, and then check if a default image directory is set. If it's not set, the program should initialize it with a predefined default path. Finally, the program should generate a thumbnail version of the cached image for faster loading times on mobile devices.",276,,"['```python
import os
from PIL import Image

class ImageCache:
    def __init__(self):
        self.cache = {}
        self.default_image_dir = None

    def load_image(self, image_path):
        if image_path not in self.cache:
            try:
                image = Image.open(image_path)
                self.cache[image_path] = image
                return image
            except IOError:
                print(""Error loading image:"", image_path)
                return None
        return self.cache[image_path]

    def set_default_image_dir(self, default_path):
        if not self.default_image_dir and os.path.exists(default_path):
            self.default_image_dir = default_path

    def generate_thumbnail(self, image_path, size=(100, 100)):
        cached_image = self.load_image(image_path)
        if cached_image:
            thumbnail = cached_image.resize(size, Image.ANTIALIAS)
            thumbnail_path = os.path.join(self.default_image_dir, ""thumbnail_"" + os.path.basename(image_path))
            thumbnail.save(thumbnail_path)
            return thumbnail_path
        else:
            print(""Image not found in cache:"", image_path)
            return None

# Example usage:
cache = ImageCache()
image_path = 'path_to_your_image.jpg'
default_path = '/path/to/default/images'

cache.set_default_image_dir(default_path)
thumbnail_path = cache.generate_thumbnail(image_path)

if thumbnail_path:
    print(""Thumbnail generated and saved at:"", thumbnail_path)
```']",38,[0],[],True,0,0,0,

