import json
from typing import Any, Dict, List, Optional, Union

class BundleNode:
    def __init__(self, key: str, value: Any):
        self.key = key
        self.value = value
        self.children: List['BundleNode'] = []

class BundleTree:
    def __init__(self):
        self.root = BundleNode("""", {})

    def add_node(self, parent: 'BundleNode', key: str, value: Any):
        new_node = BundleNode(key, value)
        if isinstance(value, dict):
            for k, v in value.items():
                self.add_node(new_node, k, v)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                self.add_node(new_node, f""{key}[{i}]"", item)
        else:
            parent.children.append(new_node)

def parse_resource(file_path: str) -> BundleTree:
