from cryptography.hazmat.backends import default_backend

def cipherFromType(cipherType):
    if cipherType == 'AES':
        return Cipher(algorithms.AES(b'secretkey1234567890'), modes.CBC(b'iv12345678901234'), backend=default_backend())
    elif cipherType == 'DES':
        return Cipher(algorithms.DES(b'key12345678'), modes.ECB(), backend=default_backend())
    else:
        raise ValueError(""Unsupported cipher type"")

def encryptState(state, cipher):
    encryptor = cipher.encryptor()
    encrypted_state = encryptor.update(state.encode()) + encryptor.finalize()
    return encrypted_state

def decryptState(encrypted_state, cipher):
    decryptor = cipher.decryptor()
    decrypted_state = decryptor.update(encrypted_state) + decryptor.finalize()
    return decrypted_state.decode()

def createStateListFromStart(startState, transitionFunction, cipherType):
    cipher = cipherFromType(cipherType)
    encryptedStates = []
    for state in startState:
        encrypted_state = encryptState(state, cipher)
        encryptedStates.append(encrypted_state)

    # Example of processing states
    processedStates = [decryptState(state, cipher) for state in encryptedStates]
    return processedStates

# Example usage
