import os
import json
from threading import Thread, Lock
from cryptography.fernet import Fernet

class ResourceBundle:
    def __init__(self, version=None):
        self.version = version
        self.data = {}

class ResourceParser:
    def __init__(self, cache_dir='cache', encryption_key=None):
        self.cache_dir = cache_dir
        self.encryption_key = encryption_key if encryption_key else Fernet.generate_key()
        self.lock = Lock()
        self.cached_bundles = {}
        self.logger = self.setup_logger()

    def setup_logger(self):
        import logging
        logger = logging.getLogger('ResourceParser')
        handler = logging.FileHandler('resource_parser.log')
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.setLevel(logging.ERROR)
        return logger

    def load_or_parse_bundle(self, path):
        if path in self.cached_bundles:
            return self.cached_bundles[path]

        try:
            with open(path, 'r') as file:
                content = file.read()
                data = self.parse_content(content)
                bundle = ResourceBundle(version=self.get_version(data))
                bundle.data = data
                self.cache_bundle(bundle, path)
                return bundle
        except Exception as e:
            self.logger.error(f""Failed to load or parse bundle: {path} - {str(e)}"")
            raise

    def cache_bundle(self, bundle, path):
        with self.lock:
            if len(self.cached_bundles) > 100:  # Simple eviction policy
                self.evict_cache()
            self.cached_bundles[path] = bundle

    def evict_cache(self):
        oldest_path = min(self.cached_bundles.keys(), key=lambda k: os.path.getmtime(k))
        del self.cached_bundles[oldest_path]

    def parse_content(self, content):
        # Custom parsing logic here
        return json.loads(content)  # Simplified for demonstration

    def get_version(self, data):
        return data.get('version', '0.1')

    def merge_bundles(self, *paths):
        merged_data = {}
        for path in paths:
            bundle = self.load_or_parse_bundle(path)
            merged_data.update(bundle.data)
        return ResourceBundle(version='merged', data=merged_data)

    def encrypt_data(self, data):
        cipher_suite = Fernet(self.encryption_key)
        encrypted_data = cipher_suite.encrypt(data.encode('utf-8'))
        return base64.b64encode(encrypted_data).decode('utf-8')

    def decrypt_data(self, encrypted_data):
        cipher_suite = Fernet(self.encryption_key)
        decrypted_data = cipher_suite.decrypt(base64.b64decode(encrypted_data))
        return decrypted_data.decode('utf-8')

def parallel_load(parser, paths):
    threads = []
    for path in paths:
        thread = Thread(target=parser.load_or_parse_bundle, args=(path,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()
