0,"Create a Python class focused on JSON manipulation. This class should encompass a method for converting data into a JSON string format and another for generating an instance from a JSON string. It should also maintain a registry of factory functions, indexed by ID, designed for creating new instances of subclass types. The implementation should include functions to add new factory functions to the registry and to instantiate a subclass using the corresponding factory function based on a given ID.",94,,"['```python
import json

class JSONManipulator:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, id, factory_func):
        cls._factory_registry[id] = factory_func

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        if 'type' in data and data['type'] in cls._factory_registry:
            return cls._factory_registry[data['type']](**data)
        else:
            raise ValueError(""Unknown type in JSON"")

    def to_json(self):
        return json.dumps(self, default=lambda o: o.__dict__, sort_keys=True, indent=4)

# Example subclass
class Person(JSONManipulator):
    def __init__(self, name, age):
        self.name = name
        self.age = age

# Registering the factory function for Person
JSONManipulator.register_factory('person', Person)

# Usage example
person_json = '{""type"": ""person"", ""name"": ""John"", ""age"": 30}'
person_instance = JSONManipulator.from_json(person_json)
print(person_instance.to_json())
```']",0,[0],[],True,0,0,0,

