def des_cipher_sum_primes(numbers):
    from Crypto.Cipher import DES

    def encrypt(number):
        try:
            cipher = DES.new(b'KEY', DES.MODE_ECB)
            encrypted = cipher.encrypt(str(number).encode())
            return encrypted.hex()
        except Exception as e:
            print(f""Error occurred during encryption: {e}"")
            return None

    def sum_primes(numbers):
        primes_sum = sum(num for num in numbers if is_prime(int(num)))
        return primes_sum

    results = [encrypt(num) for num in numbers]

    primes_sum = sum_primes(results)

    assert len(results) == len(numbers), ""Not all numbers were successfully encrypted.""

    return primes_sum
