0,"Create a Flask-based API for PROJECT_STATUS entities. Each entity should have a project ID, start date, end date, and duration. Validate instance integrity with built-in libraries. Implement endpoints for project creation, retrieval, update, and deletion. Include error handling for data and request issues.",680,,"[""```python
from flask import Flask, request, jsonify
from datetime import datetime
from pydantic import BaseModel, ValidationError

app = Flask(__name__)

# Define the PROJECT_STATUS entity using Pydantic
class ProjectStatus(BaseModel):
    project_id: int
    start_date: datetime
    end_date: datetime
    duration: int

# In-memory storage for demonstration purposes
project_statuses = []

@app.route('/projects', methods=['POST'])
def create_project():
    try:
        data = request.get_json()
        new_project = ProjectStatus(**data)
        project_statuses.append(new_project.dict())
        return jsonify(new_project.dict()), 201
    except ValidationError as e:
        return jsonify(e.errors()), 400

@app.route('/projects', methods=['GET'])
def get_projects():
    return jsonify(project_statuses), 200

@app.route('/projects/<int:project_id>', methods=['GET'])
def get_project(project_id):
    project = next((p for p in project_statuses if p['project_id'] == project_id), None)
    if project:
        return jsonify(project), 200
    else:
        return jsonify({'error': 'Project not found'}), 404

@app.route('/projects/<int:project_id>', methods=['PUT'])
def update_project(project_id):
    try:
        data = request.get_json()
        updated_data = ProjectStatus(**data).dict()
        project_index = next((i for i, p in enumerate(project_statuses) if p['project_id'] == project_id), None)
        if project_index is not None:
            project_statuses[project_index] = updated_data
            return jsonify(updated_data), 200
        else:
            return jsonify({'error': 'Project not found'}), 404
    except ValidationError as e:
        return jsonify(e.errors()), 400

@app.route('/projects/<int:project_id>', methods=['DELETE'])
def delete_project(project_id):
    project_index = next((i for i, p in enumerate(project_statuses) if p['project_id'] == project_id), None)
    if project_index is not None:
        del project_statuses[project_index]
        return jsonify({'message': 'Project deleted'}), 200
    else:
        return jsonify({'error': 'Project not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
