import time
import logging

# Set up logging configuration
logging.basicConfig(filename='app.log', level=logging.INFO, format='%(asctime)s - %(message)s')

def validate_number(num_str, min_val, max_val):
    try:
        num = int(num_str)
        if min_val <= num <= max_val:
            return True
        else:
            raise ValueError(f""Number {num} is out of the allowed range ({min_val}-{max_val})."")
    except ValueError as e:
        logging.error(e)
        print(e)
        return False

def get_valid_numbers(input_str, min_val, max_val):
    numbers = input_str.split()
    valid_numbers = []
    for num_str in numbers:
        if validate_number(num_str, min_val, max_val):
            valid_numbers.append(int(num_str))
    return valid_numbers

def sort_numbers(numbers):
    start_time = time.time()
    sorted_numbers = sorted(numbers)
    end_time = time.time()
    logging.info(f""Sorting took {end_time - start_time} seconds."")
    print(""Sorted numbers:"", sorted_numbers)
    return sorted_numbers

def find_highest_number(numbers):
    highest_number = max(numbers) if numbers else None
    print(""Highest number:"", highest_number)

def main_menu():
    while True:
        print(""\nMenu:"")
        print(""1. Validate and get numbers"")
        print(""2. Sort previous list of numbers"")
        print(""3. Display highest number from previous list"")
        print(""4. Set custom range limits"")
        print(""5. Quit"")
        choice = input(""Enter your choice: "")

        if choice == '1':
            min_val, max_val = get_custom_range()
            input_str = input(""Enter space-separated numbers: "")
            valid_numbers = get_valid_numbers(input_str, min_val, max_val)
            logging.info(f""Validated numbers: {valid_numbers}"")
        elif choice == '2':
            if not hasattr(globals(), 'sorted_numbers'):
                print(""No previous list to sort."")
                continue
            sort_numbers(sorted_numbers)
        elif choice == '3':
            if not hasattr(globals(), 'highest_number') or highest_number is None:
                print(""No previous highest number found."")
                continue
            print(""Highest number:"", highest_number)
        elif choice == '4':
            min_val, max_val = get_custom_range()
        elif choice == '5':
            break
        else:
            print(""Invalid choice. Please try again."")

def get_custom_range():
    while True:
        try:
            min_val = int(input(""Enter minimum value for the range: ""))
            max_val = int(input(""Enter maximum value for the range: ""))
            if min_val >= max_val:
                raise ValueError(""Minimum value should be less than maximum value."")
            return min_val, max_val
        except ValueError as e:
            logging.error(e)
            print(e)

if __name__ == ""__main__"":
    min_val = 1
    max_val = 100
    main_menu()
