import math

def validate_input(input_list):
    if not input_list or not all(isinstance(x, (int, float)) for x in input_list):
        raise ValueError(""Input list must be non-empty and contain only numeric values."")

def compute_sqrt_product(numbers):
    validate_input(numbers)
    product = 1
    positive_count = 0
    for number in numbers:
        try:
            sqrt_value = math.sqrt(number)
            if sqrt_value > 0:
                product *= sqrt_value
                positive_count += 1
        except ValueError:
            continue
    return product, positive_count

# Example usage:
input_numbers = [4.0, 9.0, -16.0, 25.0]
result_product, result_count = compute_sqrt_product(input_numbers)
print(f""Product of positive square roots: {result_product}, Count of positive results: {result_count}"")
