0,"Create a program that enables the user to execute fundamental bitwise operations on two integers provided as command-line arguments. The program should support bitwise AND, OR, XOR, and NOT operations. Implement options for the user to choose which operation to perform and display the result. Include error handling for invalid inputs and undefined bitwise operations.",121,,"['```python
import sys

def main():
    if len(sys.argv) != 4:
        print(""Usage: python bitwise_operations.py <operation> <num1> <num2>"")
        print(""Operations: AND, OR, XOR, NOT"")
        return 1

    operation = sys.argv[1].upper()
    num1 = None
    num2 = None

    try:
        num1 = int(sys.argv[2])
        num2 = int(sys.argv[3])
    except ValueError:
        print(""Invalid input: Please provide integers for num1 and num2."")
        return 1

    if operation == ""NOT"":
        if len(sys.argv) != 3:
            print(""Usage: python bitwise_operations.py NOT <num>"")
            return 1
        result = ~num1
    else:
        if operation not in [""AND"", ""OR"", ""XOR""]:
            print(""Invalid operation: Supported operations are AND, OR, XOR."")
            return 1
        if len(sys.argv) != 4:
            print(f""Usage: python bitwise_operations.py {operation} <num1> <num2>"")
            return 1

        if operation == ""AND"":
            result = num1 & num2
        elif operation == ""OR"":
            result = num1 | num2
        elif operation == ""XOR"":
            result = num1 ^ num2

    print(f""Result: {result}"")

if __name__ == ""__main__"":
    sys.exit(main())
```

