from typing import Dict, Any, Optional, List

class TreeNode:
    def __init__(self, key: str):
        self.key = key
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TreeNode("""")

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TreeNode(char)
            node = node.children[char]
        node.is_end_of_word = True

    def search_prefix(self, prefix: str) -> Optional[TreeNode]:
        node = self.root
        for char in prefix:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

def insert_key_after_first_occurrence(dictionary: Dict[str, Any], key1: str, key2: str, prioritized_keys: Optional[List[str]] = None, ignore_duplicates: bool = False) -> Dict[str, Any]:
    if not dictionary or not key1 or not key2:
        raise ValueError(""Dictionary and keys cannot be empty"")

    if prioritized_keys is None:
        prioritized_keys = []

    trie = Trie()
    for key in prioritized_keys:
        trie.insert(key)

    new_dict = {}
    found_key1 = False
    inserted_key2 = False

    for key, value in dictionary.items():
        if key == key1 and not found_key1:
            new_dict[key] = value
            found_key1 = True
            if not inserted_key2:
                new_dict[key2] = None  # Placeholder to be filled later
        elif key == key2 and found_key1 and not inserted_key2:
            inserted_key2 = True
        new_dict[key] = value

    if not found_key1:
        new_dict[key1] = None  # Placeholder to be filled later
        if not inserted_key2:
            new_dict[key2] = None  # Placeholder to be filled later

    return new_dict
