import requests

def update_user_status(user_id, message_category, text):
    # Validate inputs through an API call
    validation_url = ""https://api.example.com/validate""
    validation_data = {
        ""user_id"": user_id,
        ""message_category"": message_category,
        ""text"": text
    }
    response = requests.post(validation_url, json=validation_data)

    if response.status_code == 200 and response.json()[""is_valid""]:
        # Adjust the user's status
        adjustment_url = ""https://api.example.com/adjust_status""
        adjustment_data = {
            ""user_id"": user_id,
            ""new_status"": ""active""
        }
        adjustment_response = requests.post(adjustment_url, json=adjustment_data)

        if adjustment_response.status_code == 200:
            # Return success notification to the client
            return {""success"": True, ""message"": ""User status updated successfully.""}
        else:
            return {""success"": False, ""message"": ""Failed to adjust user status.""}
    else:
        return {""success"": False, ""message"": ""Invalid input data provided.""}

# Example usage
