1,"Create a Python function that reads a CSV file, filters rows based on a specific condition, calculates the average value of a column for the filtered rows, and returns the result rounded to two decimal places. Handle potential exceptions such as file not found or invalid CSV format gracefully.",94,,"['```python
import csv

def calculate_filtered_average(file_path, filter_column, filter_value, target_column):
    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            filtered_data = [row for row in reader if row[filter_column] == filter_value]

            if not filtered_data:
                return ""No data found for the given condition.""

            target_values = [float(row[target_column]) for row in filtered_data]
            average = sum(target_values) / len(target_values)

            return round(average, 2)

    except FileNotFoundError:
        return ""File not found. Please check the file path.""

    except KeyError as e:
        return f""Invalid CSV format: Column '{e}' not found.""

    except ValueError:
        return ""One or more values in the target column are not valid numbers.""

# Example usage:
result = calculate_filtered_average('data.csv', 'Category', 'Electronics', 'Price')
print(result)
