            with open(file_path, 'r') as file:
                data = json.load(file)
                return self._build_hierarchical_structure(data)
        except FileNotFoundError:
            self.logger.error(f""File not found: {file_path}"")
            return None
        except json.JSONDecodeError:
            self.logger.error(f""Invalid JSON format in {file_path}"")
            return None

    def _build_hierarchical_structure(self, data):
        if isinstance(data, dict):
            structure = {}
            for key, value in data.items():
                if isinstance(value, list):
                    structure[key] = [self._build_hierarchical_structure(item) for item in value]
                elif isinstance(value, dict):
                    structure[key] = self._build_hierarchical_structure(value)
                else:
                    structure[key] = value
            return structure

