from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_jwt_extended import JWTManager, jwt_required, create_access_token, get_jwt_identity

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///project_status.db'
app.config['JWT_SECRET_KEY'] = 'your_secret_key'

db = SQLAlchemy(app)
limiter = Limiter(app, key_func=get_remote_address)
jwt = JWTManager(app)

class Project(db.Model):
    project_id = db.Column(db.Integer, primary_key=True)
    start_date = db.Column(db.DateTime, nullable=False)
    end_date = db.Column(db.DateTime, nullable=False)
    duration = db.Column(db.Integer, nullable=False)
    name = db.Column(db.String(100), nullable=False)
    status = db.Column(db.String(50), nullable=False)
    priority = db.Column(db.Integer, nullable=False)
    tasks = db.relationship('Task', backref='project', lazy=True)
    milestones = db.relationship('Milestone', backref='project', lazy=True)

class Task(db.Model):
    task_id = db.Column(db.Integer, primary_key=True)
    project_id = db.Column(db.Integer, db.ForeignKey('project.project_id'), nullable=False)
    name = db.Column(db.String(100), nullable=False)
    status = db.Column(db.String(50), nullable=False)
    priority = db.Column(db.Integer, nullable=False)

class Milestone(db.Model):
    milestone_id = db.Column(db.Integer, primary_key=True)
    project_id = db.Column(db.Integer, db.ForeignKey('project.project_id'), nullable=False)
    name = db.Column(db.String(100), nullable=False)
    status = db.Column(db.String(50), nullable=False)
    priority = db.Column(db.Integer, nullable=False)

@app.route('/projects', methods=['GET'])
@limiter.limit(""20 per minute"")
def get_projects():
    status = request.args.get('status')
    priority = request.args.get('priority')
    query = Project.query
    if status:
        query = query.filter(Project.status == status)
    if priority:
        query = query.filter(Project.priority == int(priority))
    projects = query.all()
    return jsonify([{'project_id': project.project_id, 'name': project.name} for project in projects])

@app.route('/projects/<int:id>', methods=['GET'])
@limiter.limit(""10 per minute"")
def get_project(id):
    project = Project.query.get_or_404(id)
    return jsonify({'project_id': project.project_id, 'name': project.name})

@app.route('/projects', methods=['POST'])
@jwt_required()
@limiter.limit(""5 per minute"")
def create_project():
    data = request.get_json()
    new_project = Project(
        start_date=data['start_date'],
        end_date=data['end_date'],
        duration=data['duration'],
        name=data['name'],
        status=data['status'],
        priority=data['priority']
    )
    db.session.add(new_project)
    db.session.commit()
    return jsonify({'project_id': new_project.project_id, 'name': new_project.name}), 201

@app.route('/projects/<int:id>', methods=['PATCH'])
@jwt_required()
@limiter.limit(""3 per minute"")
def update_project(id):
    project = Project.query.get_or_404(id)
    data = request.get_json()
    if 'status' in data:
        project.status = data['status']
    if 'priority' in data:
        project.priority = data['priority']
    db.session.commit()
    return jsonify({'project_id': project.project_id, 'name': project.name})

@app.route('/projects/<int:id>', methods=['DELETE'])
@jwt_required()
@limiter.limit(""2 per minute"")
def delete_project(id):
    project = Project.query.get_or_404(id)
    db.session.delete(project)
    db.session.commit()
    return jsonify({'message': 'Project deleted'})

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
