from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///project_status.db'
db = SQLAlchemy(app)

class ProjectStatus(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    project_id = db.Column(db.String(100), nullable=False)
    start_date = db.Column(db.DateTime(), nullable=False)
    end_date = db.Column(db.DateTime(), nullable=False)
    duration = db.Column(db.Integer(), nullable=False)

@app.route('/project_status', methods=['POST'])
def create_project():
    data = request.get_json()
    project = ProjectStatus(project_id=data['project_id'], start_date=data['start_date'], end_date=data['end_date'], duration=data['duration'])
    try:
        db.session.add(project)
        db.session.commit()
        return {'message': 'Project created successfully'}, 201
    except Exception as e:
        db.session.rollback()
        return {'error': str(e)}, 400

@app.route('/project_status/<int:id>', methods=['GET'])
def get_project(id):
    project = ProjectStatus.query.get_or_404(id)
    return {
        'project_id': project.project_id,
        'start_date': project.start_date,
        'end_date': project.end_date,
        'duration': project.duration
    }, 200

@app.route('/project_status/<int:id>', methods=['PUT'])
def update_project(id):
    data = request.get_json()
    project = ProjectStatus.query.get_or_404(id)
    try:
        project.project_id = data['project_id']
        project.start_date = data['start_date']
        project.end_date = data['end_date']
        project.duration = data['duration']
        db.session.commit()
        return {'message': 'Project updated successfully'}, 200
    except Exception as e:
        db.session.rollback()
        return {'error': str(e)}, 400

@app.route('/project_status/<int:id>', methods=['DELETE'])
def delete_project(id):
    project = ProjectStatus.query.get_or_404(id)
    try:
        db.session.delete(project)
        db.session.commit()
        return {'message': 'Project deleted successfully'}, 200
    except Exception as e:
        db.session.rollback()
        return {'error': str(e)}, 400

