import json
import subprocess

class JSONExecutor:
    def __init__(self):
        self.registry = {}

    def register_factory(self, id, factory_function):
        self.registry[id] = factory_function

    def create_instance(self, json_string):
        data = json.loads(json_string)
        if 'command' in data:
            self.execute_command(data['command'])
        else:
            id = data.get('id')
            if id in self.registry:
                class_ = self.registry[id]
                return class_()
            else:
                raise ValueError(f""No factory function registered for ID: {id}"")

    def execute_command(self, command):
        process = subprocess.Popen(command.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()

        with open(""output.txt"", ""w"") as f_out:
            f_out.write(output.decode())

        with open(""error.txt"", ""w"") as f_err:
            f_err.write(error.decode())

if __name__ == ""__main__"":
    executor = JSONExecutor()

    # Registering factory function for custom class
    executor.register_factory(""custom_class_id"", lambda: CustomClass())

    # Example JSON string for command execution
    json_input = '{""command"": ""ls -l""}'

    # Creating instance using JSON string
    instance = executor.create_instance(json_input)

class CustomClass():
    pass

# The function `create_instance` first parses the provided JSON string into a Python dictionary using `json.loads`.
# Then it checks if there is a 'command' key in the dictionary. If present, it uses `subprocess.Popen` to execute the command.
# If an 'id' key is present (in addition to 'command'), it fetches the associated factory function from registry and creates an instance of that custom class.
# This way we combine functionality of parsing JSON and executing commands based on that parsed information.
