import sys

def perform_bitwise_operation(a, b, operation):
    if operation == 'AND':
        return a & b
    elif operation == 'OR':
        return a | b
    elif operation == 'XOR':
        return a ^ b
    elif operation == 'NOT':
        return ~a
    else:
        raise ValueError(""Invalid operation"")

