import sys

def get_user_input():
    try:
        num1 = int(input(""Enter first number: ""))
        num2 = int(input(""Enter second number: ""))
        return num1, num2
    except ValueError:
        print(""Invalid input. Please enter integers."")
        sys.exit(1)

def perform_operation(num1, num2, operation):
    if operation == 'AND':
        return num1 & num2
    elif operation == 'OR':
        return num1 | num2
    elif operation == 'XOR':
        return num1 ^ num2
    elif operation == 'NOT':
        return ~num2  # Assuming NOT is applied to the second number as an example
    else:
        print(""Undefined operation. Please choose from AND, OR, XOR, or NOT."")
        sys.exit(1)

def main():
    operations = ['AND', 'OR', 'XOR', 'NOT']
