def create_custom_list(size, min_val, max_val):
    return [CustomItem(random.randint(min_val, max_val)) for _ in range(size)]

def calculate_distance(item1, item2):
    return math.sqrt((item1.value - item2.value)**2)

def find_nearest_neighbor(custom_list, target_value):
    nearest_item = custom_list[0]
    min_distance = calculate_distance(custom_list[0], target_value)

    for index, item in enumerate(custom_list[1:], start=1):
        distance = calculate_distance(item, target_value)
        if distance < min_distance:
            min_distance = distance
            nearest_item = item

    return nearest_item.value, index

# Example usage
