0,"Develop a new class named `DataProcessor` that processes a JSON file containing sensitive data. The class should include methods for loading the JSON data, encrypting it using the Fernet encryption library, and logging any errors that occur during the process. Additionally, implement a method to decrypt the processed data and return it in a specific format. The class should also handle exceptions such as file not found or invalid JSON format by logging appropriate error messages.",121,,"['```python
from cryptography.fernet import Fernet
import json
import logging

class DataProcessor:
    def __init__(self, key=None):
        self.key = key or Fernet.generate_key()
        self.cipher_suite = Fernet(self.key)
        logging.basicConfig(level=logging.ERROR)

    def load_json(self, file_path):
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            logging.error(f""File not found: {file_path}"")
            raise
        except json.JSONDecodeError:
            logging.error(f""Invalid JSON format in file: {file_path}"")
            raise

    def encrypt_data(self, data):
        try:
            encrypted_data = self.cipher_suite.encrypt(json.dumps(data).encode())
            return encrypted_data
        except Exception as e:
            logging.error(f""Error encrypting data: {e}"")
            raise

    def decrypt_data(self, encrypted_data):
        try:
            decrypted_data = self.cipher_suite.decrypt(encrypted_data)
            return json.loads(decrypted_data.decode())
        except Exception as e:
            logging.error(f""Error decrypting data: {e}"")
            raise
