import xml.etree.ElementTree as ET

def parse_xml(file_path):
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()

        data_elements = []
        for element in root.iter():
            tag = element.tag
            attributes = element.attrib
            data_elements.append((tag, attributes))

        return data_elements
    except ET.ParseError as e:
        print(f""Error parsing XML file: {e}"")
        return None

def validate_data(data_elements):
    valid_data = []
    for tag, attributes in data_elements:
        # Example validation rules
        if 'date' in attributes:
            try:
                datetime.datetime.strptime(attributes['date'], '%Y-%m-%d')
                valid_data.append((tag, attributes))
            except ValueError:
                print(f""Invalid date format for tag: {tag}"")
        elif 'name' in attributes and not attributes['name']:
            print(f""Empty name attribute for tag: {tag}"")
        else:
            valid_data.append((tag, attributes))

    return valid_data

def main():
    file_path = input(""Enter the XML file path: "")
    data_elements = parse_xml(file_path)
    if data_elements is not None:
        valid_data = validate_data(data_elements)
        print(""Valid Data:"")
        for tag, attributes in valid_data:
            print(f""Tag: {tag}, Attributes: {attributes}"")

if __name__ == ""__main__"":
    main()
