import random

class CustomItem:
    def __init__(self, value):
        self.value = value

def generate_custom_items(count, min_val, max_val):
    return [CustomItem(random.randint(min_val, max_val)) for _ in range(count)]

def euclidean_distance(item1, item2):
    return abs(item1.value - item2.value)

def find_nearest_item(custom_list, target_value):
    closest_index = 0
    min_distance = float('inf')

    for index, item in enumerate(custom_list):
        distance = euclidean_distance(item, CustomItem(target_value))
        if distance < min_distance:
            min_distance = distance
            closest_index = index

    return custom_list[closest_index].value, closest_index

# Example usage
