import random

class DSCP_PRECEDENCE_MAP_T:
    def __init__(self, ip_priority, diffserv_code):
        self.ip_priority = ip_priority
        self.diffserv_code = diffserv_code

def generate_dscp_precedence_mapping(list_size, seed=None):
    if not isinstance(list_size, int) or list_size <= 0:
        raise ValueError(""List size must be a positive integer."")
    if seed is not None and not isinstance(seed, int):
        raise ValueError(""Seed must be an integer or None."")

    random.seed(seed)
    precedence_mapping = []
    for _ in range(list_size):
        ip_priority = random.randint(0, 7)  # Assuming IP_PRIORITY ranges from 0 to 7
        diffserv_code = random.randint(0, 63)  # Assuming DIFFServ_CODE ranges from 0 to 63
        precedence_mapping.append(DSCP_PRECEDENCE_MAP_T(ip_priority, diffserv_code))
    return precedence_mapping

# Example usage:
mapping = generate_dscp_precedence_mapping(5, seed=42)
for item in mapping:
    print(f""IP Priority: {item.ip_priority}, DIFFServ Code: {item.diffserv_code}"")
