```python
import random
import math

class CustomItem:
    def __init__(self, value):
        self.value = value

def create_custom_list(size, min_val, max_val):
    return [CustomItem(random.randint(min_val, max_val)) for _ in range(size)]

def calculate_distance(item1, item2):
    return math.sqrt((item1.value - item2.value)**2)

def find_nearest_neighbor(custom_list, target_value):
    nearest_item = custom_list[0]
    min_distance = calculate_distance(custom_list[0], CustomItem(target_value))

    for index, item in enumerate(custom_list[1:], start=1):
        distance = calculate_distance(item, CustomItem(target_value))
        if distance < min_distance:
            min_distance = distance
            nearest_item = item

    return nearest_item.value, index

# Example usage
custom_items = create_custom_list(10, 0, 100)
target_value = 55.5
closest_value, closest_index = find_nearest_neighbor(custom_items, target_value)
print(f""The closest value to {target_value} is {closest_value} at index {closest_index}."")
```']",0,[0],[],True,0,0,0,

