import sys

def and_operation(a, b):
    return a & b

def or_operation(a, b):
    return a | b

def xor_operation(a, b):
    return a ^ b

def not_operation(a):
    return ~a

def main():
    if len(sys.argv) != 5:
        print(""Usage: python bitwise_calculator.py <operation> <num1> <num2>"")
        sys.exit(1)

    operation = sys.argv[1]
    num1 = sys.argv[2]
    num2 = sys.argv[3]

    try:
        num1, num2 = int(num1), int(num2)
    except ValueError:
        print(""Error: Both inputs must be integers."")
        sys.exit(1)

    if operation not in ['and', 'or', 'xor', 'not']:
        print(""Error: Invalid operation. Choose from 'and', 'or', 'xor', 'not'."")
        sys.exit(1)

    if operation == 'and':
        result = and_operation(num1, num2)
    elif operation == 'or':
        result = or_operation(num1, num2)
    elif operation == 'xor':
        result = xor_operation(num1, num2)
    else:
        result = not_operation(num1)

    print(f""Result: {result}"")

if __name__ == ""__main__"":
    main()
