class DynamicTimer:
    def __init__(self, duration):
        if duration < 0:
            raise ValueError(""Duration must be non-negative"")
        self.duration = duration
        self.current_time = duration
        self.running = False

    def start(self):
        if not self.running and self.current_time > 0:
            self.running = True
            return self.current_time
        elif self.current_time == 0:
            raise ValueError(""Timer is already at zero"")
        else:
            raise ValueError(""Timer cannot be started"")

    def stop(self):
        if self.running:
            self.running = False
            return self.current_time

    def reset(self):
        self.current_time = self.duration
        self.running = False
        return self.current_time

    def get_remaining_time(self):
        if not self.running and self.current_time == 0:
            raise ValueError(""Timer is stopped and at zero"")
        elif not self.running:
            return self.current_time
        else:
            import time
            start_time = time.time()
            while time.time() - start_time < 1 and self.running:
                pass
            return max(0, self.current_time - int(time.time() - start_time))

    def is_running(self):
        return self.running

    def adjust_duration(self, new_duration):
        if new_duration < 0:
            raise ValueError(""New duration must be non-negative"")
        self.duration = new_duration
        self.current_time = min(self.current_time, new_duration)
