import time
import logging

def validate_number(num, min_limit, max_limit):
    try:
        num = int(num)
        return min_limit <= num <= max_limit
    except ValueError:
        return False

def get_valid_numbers(input_string, min_limit=1, max_limit=100):
    valid_numbers = []
    while True:
        user_input = input(input_string)
        for num in user_input.split():
            if validate_number(num, min_limit, max_limit):
                valid_numbers.append(int(num))
            else:
                print(f""Invalid number: {num}. Please try again."")
                break
        else:
            break

    return valid_numbers

def sort_and_log_numbers(numbers):
    sorted_numbers = sorted(numbers)
    log_message = ""Sorted numbers: "" + ', '.join(map(str, sorted_numbers))
    logging.info(log_message)
    return sorted_numbers

def display_results(sorted_numbers, highest_number):
    print(f""Highest number: {highest_number}"")

    display_choice = input(""Do you want to display both highest and sorted list? (y/n): "")

    if display_choice.lower() == 'y':
        print(f""Sorted numbers: {', '.join(map(str, sorted_numbers))}"")

def main():
    logging.basicConfig(filename='operation_log.txt', level=logging.INFO)

    operation_choices = {
        '1': 'Validate new string',
        '2': 'Sort previous list of numbers',
        '3': 'Quit'
    }

    while True:
        print(""\nMenu:"")
        for key, value in operation_choices.items():
            print(f""{key}. {value}"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            input_string = f""Enter a string of space-separated numbers between {min_limit} and {max_limit}: ""
            numbers_list = get_valid_numbers(input_string)

            highest_number = max(numbers_list)

            sort_and_log_numbers(numbers_list)

            display_results(numbers_list, highest_number)

main()
