import re
from math import sqrt

def process_data(numbers, text):
    if not all(isinstance(num, (int, float)) for num in numbers) or len(numbers) == 0:
        raise ValueError(""Invalid input list. It should contain only numeric values and be non-empty."")

    product = 1
    for num in numbers:
        if num > 0:
            result = sqrt(num)
            product *= result

    book_names = re.findall(r'\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Songs|Isaiah |Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum/Habakkuk/Zephaniah/Zechariah/Malachi)\b', text, re.IGNORECASE)
    book_count = {name: book_names.count(name) for name in set(book_names)}

    return product, book_count

def generate_nfaapi_crc_indication_pdu_array(N):
    nfaapi_array = [NFAPI_CRC_INDICATION_PDU_T() for _ in range(N)]

