import sys

def main():
    if len(sys.argv) != 4:
        print(""Usage: python script.py <number1> <operation> <number2>"")
        return

    num1 = float(sys.argv[1])
    operation = sys.argv[2]
    num2 = float(sys.argv[3])

    try:
        if operation == '+':
            result = num1 + num2
        elif operation == '-':
            result = num1 - num2
        elif operation == '*':
            result = num1 * num2
        elif operation == '/':
            if num2 == 0:
                print(""Error: Division by zero"")
                return
            result = num1 / num2
        else:
            print(""Error: Invalid operation"")
            return

        print(f""Result: {result}"")
    except ValueError:
        print(""Error: Invalid number input"")

if __name__ == ""__main__"":
    main()
