import math

def process_data(numbers, text):
    if not numbers:
        return None

    product = 1
    for num in numbers:
        try:
            sqrt_num = math.sqrt(num)
            if sqrt_num > 0:
                product *= sqrt_num
        except ValueError:
            continue

    bible_books = {
        ""Genesis"": 0,
        ""Exodus"": 0,
        ""Leviticus"": 0,
        ""Numbers"": 0,
        ""Deuteronomy"": 0,
        # Add more Bible books as needed
    }

    for book in re.findall(r'\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy)\b', text):
        bible_books[book] += 1

    return product, bible_books
