import sys

def bitwise_operations(x, y, operation):
    try:
        x = int(x)
        y = int(y)
    except ValueError:
        return ""Error: Invalid input. Please provide two integers.""

    if operation == ""AND"":
        return x & y
    elif operation == ""OR"":
        return x | y
    elif operation == ""XOR"":
        return x ^ y
    elif operation == ""NOT"":
        if len(sys.argv) != 4:
            return ""Error: Invalid number of arguments. Provide 'NOT' and one integer.""
        result = ~x
        if result.bit_length() > 32:
            return ""Error: Result exceeds 32 bits.""
        return result & ((1 << 32) - 1)
    else:
        return ""Error: Undefined operation. Choose 'AND', 'OR', 'XOR', or 'NOT'.""

def main():
    if len(sys.argv) < 4:
        print(""Usage: python program.py [operation] [integer]"")
    else:
        operation = sys.argv[1]
        number1 = sys.argv[2]

        # Error handling for multiple NOT operations
        if operation == ""NOT"" and number1 != ""-"":
            print(""Error: Multiple NOT operations are not allowed."")
            sys.exit(1)

        result = bitwise_operations(number1, sys.argv[3], operation)

        if isinstance(result, str):
            print(result)
            sys.exit(1)

