import argparse
import logging
import sys

# Initialize logging configuration
logging.basicConfig(filename='bitwise_operations.log', level=logging.INFO)

def perform_operation(operators, numbers):
    if operators == 'AND':
        return all(numbers)
    elif operators == 'OR':
        return any(numbers)
    elif operators == 'XOR':
        result = numbers[0]
        for num in numbers[1:]:
            result ^= num
        return result
    elif operators == 'NOT':
        return ~numbers[0]
    else:
        raise ValueError(""Invalid operator"")

def handle_custom_operator(operators, numbers):
    if operators.startswith('CUSTOM'):
        custom_function = eval(operators.split(':')[1])
        return custom_function(numbers)
    return perform_operation(operators, numbers)

def convert_to_base(number, base):
    if base == 'binary':
        return bin(number)
    elif base == 'octal':
        return oct(number)
    elif base == 'hexadecimal':
        return hex(number)
    else:
        raise ValueError(""Invalid base"")

def main():
    parser = argparse.ArgumentParser(description='Bitwise Operation Calculator')
    parser.add_argument('operators', help='AND, OR, XOR, NOT, or custom operator')
    parser.add_argument('numbers', nargs='+', type=int, help='List of integers for operation')
    parser.add_argument('--base', choices=['binary', 'octal', 'hexadecimal'], default='decimal', help='Number base')
    args = parser.parse_args()

    try:
        numbers = [int(convert_to_base(num, args.base), 0) for num in args.numbers]
        result = handle_custom_operator(args.operators, numbers)
        logging.info(f'Operation: {args.operators}({numbers}) = {result}')
        print(result)
    except Exception as e:
        logging.error(f'Error: {e}')
        sys.exit(1)

if __name__ == '__main__':
    main()
