def install_dependencies():
    subprocess.run(['pip', 'install', '-r', 'requirements.txt'])

def setup_django_project():
    project_dir = 'django_project'
    if not os.path.exists(project_dir):
        os.mkdir(project_dir)
        os.chdir(project_dir)
        subprocess.run(['python', '-m', 'venv', 'venv'])
        activate_script = os.path.join('venv', 'Scripts', 'activate') if os.name == 'nt' else os.path.join('venv', 'bin', 'activate')
        os.system(f'source {activate_script}')
        install_dependencies()
    os.chdir(project_dir)
    subprocess.run(['django-admin', 'startapp', 'app'])

class DNSRecord:
    def __init__(self):
        self.records = {}

    def add(self, domain, record_type, value):
        if domain not in self.records:
            self.records[domain] = {}
        self.records[domain][record_type] = value

    def get_by_domain(self, domain):
        return self.records.get(domain, {})

    def list_all_records(self):
        return self.records

    def save_to_json(self, filename='dns_records.json'):
        with open(filename, 'w') as file:
            json.dump(self.records, file, indent=4)

    @staticmethod
    def load_saved_records(filename='dns_records.json'):
        if os.path.exists(filename):
            with open(filename, 'r') as file:
                return DNSRecord(**json.load(file))
        return DNSRecord()

def create_and_save_dns_resolver(resolver=None):
    if resolver is None:
        resolver = DNSRecord()
    resolver.add('example.com', 'A', '192.0.2.1')
    resolver.save_to_json()
    return resolver

def main():
    install_dependencies()
    setup_django_project()
    create_and_save_dns_resolver()

if __name__ == ""__main__"":
    main()
