2,"Design a software application enabling users to execute fundamental arithmetic tasks on two figures input through the command-line interface. The system should facilitate selection among addition, subtraction, multiplication, and division operations. Integrate an interactive feature permitting users to select the desired operation and present the outcome. Incorporate safeguards against erroneous inputs and division by zero scenarios.",121,,"['```python
import sys

def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        print(""Error: Division by zero is not allowed."")
        return None
    else:
        return x / y

def main():
    while True:
        print(""Select operation:"")
        print(""1. Add"")
        print(""2. Subtract"")
        print(""3. Multiply"")
        print(""4. Divide"")

        choice = input(""Enter choice(1/2/3/4): "")

        if choice in ['1', '2', '3', '4']:
            try:
                num1 = float(input(""Enter first number: ""))
                num2 = float(input(""Enter second number: ""))

                if choice == '1':
                    print(f""{num1} + {num2} = {add(num1, num2)}"")
                elif choice == '2':
                    print(f""{num1} - {num2} = {subtract(num1, num2)}"")
                elif choice == '3':
                    print(f""{num1} * {num2} = {multiply(num1, num2)}"")
                elif choice == '4':
                    result = divide(num1, num2)
                    if result is not None:
                        print(f""{num1} / {num2} = {result}"")
            except ValueError:
                print(""Invalid input. Please enter numeric values."")
        else:
            print(""Invalid input. Please select a valid operation."")

        next_calculation = input(""Do you want to perform another calculation? (yes/no): "")
        if next_calculation.lower() != 'yes':
            break

if __name__ == ""__main__"":
    main()
