def most_frequent_number(numbers, size):
    frequency = {}
    max_frequency = 0
    result = None

    for i in range(size):
        if numbers[i] not in frequency:
            frequency[numbers[i]] = 1
        else:
            frequency[numbers[i]] += 1

        if frequency[numbers[i]] > max_frequency:
            max_frequency = frequency[numbers[i]]
            result = numbers[i]

    return result

def main():
    try:
        size = int(input(""Enter the number of integers in the list: ""))
        if size <= 0:
            print(""The number of integers must be greater than zero."")
            return

        numbers = []
        for i in range(size):
            num = int(input(f""Enter integer {i+1}: ""))
            numbers.append(num)

        result = most_frequent_number(numbers, size)
        print(f""The most frequently occurring number is: {result}"")

