NFAPI_CRC_INDICATION_PDU_T** generateNFAPIList(int numPdu) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the array of pointers
    NFAPI_CRC_INDICATION_PDU_T** nfaPtrArray = malloc(numPdu * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (nfaPtrArray == NULL) {
        return NULL; // Handle out-of-memory error
    }

    // Allocate memory for each structure
    for (int i = 0; i < numPdu; i++) {
        nfaPtrArray[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfaPtrArray[i] == NULL) {
            free(nfaPtrArray);
            return NULL; // Handle out-of-memory error
        }

        // Generate RX_UE_INFORMATION_TAG and RNTI values based on the index
        nfaPtrArray[i]->RX_UE_INFORMATION_TAG = i + 1;
        nfaPtrArray[i]->RNTI = rand() % 0xFFFF;

