            nfaPtrArray[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = 1; // TRUE
        } else {
            nfaPtrArray[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // FALSE
        }
    }

    return nfaPtrArray;
}
