import random

class NetworkDevice:
    def __init__(self, mac_address, ip_address, port_number):
        self.mac_address = mac_address
        self.ip_address = ip_address
        self.port_number = port_number

def generate_mac_address():
    return ':'.join(f'{random.randint(0, 255):02x}' for _ in range(6))

def get_random_ip_address():
    ip_addresses = [
        ""192.168.1.1"", ""192.168.1.2"", ""192.168.1.3"", ""192.168.1.4"",
        ""10.0.0.1"", ""10.0.0.2"", ""10.0.0.3"", ""10.0.0.4""
    ]
    return random.choice(ip_addresses)

def generate_network_devices(num_devices):
    network_devices = []
    port_number = 8080
    for _ in range(num_devices):
        mac_address = generate_mac_address()
        ip_address = get_random_ip_address()
        device = NetworkDevice(mac_address, ip_address, port_number)
        network_devices.append(device)
        port_number += 1
    return network_devices

# Example usage:
devices = generate_network_devices(5)
for device in devices:
    print(f""MAC: {device.mac_address}, IP: {device.ip_address}, Port: {device.port_number}"")
