0,"Design a software application to manage a playlist of media files. Each file has a unique identifier, estimated playing time, and status (playing, paused, completed). Display media as playing, track progress through the playlist, notify completion or pause status changes. Enable users to shuffle the order of media in the playlist or play specific files at any position. Handle multiple instances of the same media type with different IDs and durations.",589,,"['```python
class MediaFile:
    def __init__(self, file_id, title, duration):
        self.file_id = file_id
        self.title = title
        self.duration = duration
        self.status = ""ready""

class Playlist:
    def __init__(self):
        self.media_files = []
        self.current_index = 0

    def add_media(self, media_file):
        self.media_files.append(media_file)

    def play_next(self):
        if self.current_index < len(self.media_files):
            current_media = self.media_files[self.current_index]
            current_media.status = ""playing""
            print(f""Playing: {current_media.title}"")
            self.current_index += 1
        else:
            print(""Playlist completed."")

    def pause(self):
        if self.current_index < len(self.media_files) and self.media_files[self.current_index].status == ""playing"":
            current_media = self.media_files[self.current_index]
            current_media.status = ""paused""
            print(f""Paused: {current_media.title}"")

    def resume(self):
        if self.current_index < len(self.media_files) and self.media_files[self.current_index].status == ""paused"":
            current_media = self.media_files[self.current_index]
            current_media.status = ""playing""
            print(f""Resuming: {current_media.title}"")

    def shuffle(self):
        import random
        random.shuffle(self.media_files)
        print(""Playlist shuffled."")

    def play_at_position(self, position):
        if 0 <= position < len(self.media_files):
            self.current_index = position
            self.play_next()
        else:
            print(""Invalid position."")

# Example usage
playlist = Playlist()
media1 = MediaFile(1, ""Song A"", 300)
media2 = MediaFile(2, ""Song B"", 450)
playlist.add_media(media1)
playlist.add_media(media2)

playlist.play_next()  # Play Song A
playlist.pause()       # Pause Song A
playlist.resume()      # Resume Song A
playlist.shuffle()     # Shuffle playlist
playlist.play_at_position(1)  # Play Song B from position 1
```']",0,[0],[],True,0,0,0,

