Implement an `evaluate_performance` function that calls these methods on a given file named 'data.csv'. The function should output a summary report detailing the average, median, mode, variance of the processed data, and any outliers that were removed.",680,,"['```python
import csv
from scipy import stats
from collections import Counter

class DataAnalyzer:
    def __init__(self, filename):
        try:
            with open(filename, 'r') as file:
                self.data = list(map(float, file.read().split(',')))
            self.average = sum(self.data) / len(self.data)
            self.median = stats.median(self.data)
            self.mode = Counter(self.data).most_common(1)[0][0]
        except FileNotFoundError:
            print(""Error: File not found."")
        except ValueError:
            print(""Error: Invalid data in file."")

    def filter_outliers(self):
        q1, q3 = stats.iqr(self.data)
        iqr = q3 - q1
        self.filtered_data = [x for x in self.data if (q1 - 1.5 * iqr <= x <= q3 + 1.5 * iqr)]

    def calculate_variance(self):
        return sum((x - self.average) ** 2 for x in self.filtered_data) / len(self.filtered_data)

def evaluate_performance(filename):
    analyzer = DataAnalyzer(filename)
    if hasattr(analyzer, 'data'):
        analyzer.filter_outliers()
        variance = analyzer.calculate_variance()
        print(f""Summary Report:"")
        print(f""Average: {analyzer.average}"")
        print(f""Median: {analyzer.median}"")
        print(f""Mode: {analyzer.mode}"")
        print(f""Variance of filtered data: {variance}"")
        if hasattr(analyzer, 'filtered_data') and len(analyzer.filtered_data) != len(analyzer.data):
            removed_outliers = [x for x in analyzer.data if x not in analyzer.filtered_data]
            print(f""Outliers removed: {removed_outliers}"")
        else:
            print(""No outliers detected."")
    else:
        print(""Data analysis failed."")

evaluate_performance('data.csv')
