import sys

def perform_operation(a, b, operation):
    if operation == '+':
        return a + b
    elif operation == '-':
        return a - b
    elif operation == '*':
        return a * b
    elif operation == '/':
        if b != 0:
            return a / b
        else:
            raise ValueError(""Division by zero is not allowed."")
    else:
        raise ValueError(""Invalid operation selected."")

def main():
    if len(sys.argv) != 4:
        print(""Usage: script.py <number1> <number2> <operation>"")
        sys.exit(1)

    try:
        num1 = float(sys.argv[1])
        num2 = float(sys.argv[2])
    except ValueError:
        print(""Error: Invalid number format"")
        sys.exit(1)

    operations = ['+', '-', '*', '/']

    try:
        op = sys.argv[3]

        if op not in operations:
            print(f""Error: Invalid operation '{op}'"")
            print(f""Valid operations are: {', '.join(operations)}"")
            sys.exit(1)

        result = perform_operation(num1, num2, op)

        print(f""{num1} {op} {num2} = {result}"")

    except ValueError as e:
        print(e)

if __name__ == ""__main__"":
    main()
